        <div class="tc-aa__actions"><a class="tc-aa__button" href="<?php echo e(request()->fullUrl()); ?>"><i class="bi bi-arrow-clockwise"></i> Actualizar</a><?php if($puedeExportarAuditoria): ?><details class="tc-audit__export-menu"><summary class="tc-aa__button tc-aa__button--primary"><i class="bi bi-download"></i> Exportar auditoría <i class="bi bi-chevron-down"></i></summary><div class="tc-audit__export-options"><a href="<?php echo e(route('management.reports.preview.export', ['tipo' => 'operaciones', 'format' => 'pdf'] + request()->query())); ?>"><i class="bi bi-file-earmark-pdf"></i><span><strong>Exportar PDF</strong><small>Documento imprimible</small></span></a><a href="<?php echo e(route('management.reports.preview.export', ['tipo' => 'operaciones', 'format' => 'excel'] + request()->query())); ?>"><i class="bi bi-file-earmark-spreadsheet"></i><span><strong>Exportar Excel</strong><small>Archivo compatible .xlsx</small></span></a><a href="<?php echo e(route('management.reports.preview.export', ['tipo' => 'operaciones', 'format' => 'csv'] + request()->query())); ?>"><i class="bi bi-filetype-csv"></i><span><strong>Exportar CSV</strong><small>Datos delimitados</small></span></a></div></details><?php endif; ?></div>
