    <div class="tc-aa__metrics tc-audit__metrics"><?php $__currentLoopData = $pagina['metricas']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $metrica): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><article class="tc-aa__metric tc-aa__metric--<?php echo e($metrica[3]); ?>"><span class="tc-aa__metric-icon"><i class="bi <?php echo e($metrica[2]); ?>"></i></span><div><span><?php echo e($metrica[0]); ?></span><strong><?php echo e($metrica[1]); ?></strong><small>Fuente: MariaDB</small></div></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div>

    <form method="GET" class="tc-aa__card tc-audit__filters" aria-label="Filtros de consulta"><h2><i class="bi bi-funnel"></i> Filtros de consulta</h2><div class="tc-audit__filter-grid"><?php $__currentLoopData = $pagina['filtros']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as [$etiqueta, $nombreCampo, $marcador]): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label><?php echo e($etiqueta); ?><?php if($marcador === 'fecha'): ?><input type="date" name="<?php echo e($nombreCampo); ?>" value="<?php echo e($filtros[$nombreCampo] ?? ''); ?>"><?php elseif($marcador === 'text'): ?><input type="search" name="<?php echo e($nombreCampo); ?>" value="<?php echo e($filtros[$nombreCampo] ?? ''); ?>" maxlength="120"><?php else: ?><select name="<?php echo e($nombreCampo); ?>"><option value=""><?php echo e($marcador); ?></option><?php $__currentLoopData = $pagina['opcionesFiltros'][$nombreCampo] ?? []; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $valor => $texto): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($valor); ?>" <?php if((string) ($filtros[$nombreCampo] ?? '') === (string) $valor): echo 'selected'; endif; ?>><?php echo e($texto); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><?php endif; ?></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><button type="submit" class="tc-aa__button tc-aa__button--primary"><i class="bi bi-funnel"></i> Filtrar</button><a class="tc-aa__button" href="<?php echo e(route(request()->route()->getName())); ?>"><i class="bi bi-eraser"></i> Limpiar</a></div></form>

    <div class="tc-audit__workspace"><section class="tc-aa__card tc-audit__table-card"><div class="tc-aa__card-heading"><div><h2>Eventos registrados</h2><small>Mostrando <?php echo e($pagina['paginacion']->firstItem() ?? 0); ?>–<?php echo e($pagina['paginacion']->lastItem() ?? 0); ?> de <?php echo e($pagina['paginacion']->total()); ?> registros</small></div><span>Consulta de solo lectura</span></div><div class="tc-aa__table-wrap"><table class="tc-audit__table"><thead><tr><th>Fecha y hora</th><th>Usuario</th><th>Operación</th><th>Módulo</th><th>Registro afectado</th><th>Resultado</th><th>Acciones</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $pagina['detalles']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $detalle): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr data-audit-row data-audit-id="<?php echo e($detalle['id']); ?>"><td><?php echo e($detalle['fecha']); ?></td><td><?php echo e($detalle['usuario']); ?></td><td><?php echo e($detalle['accion']); ?></td><td><?php echo e($detalle['modulo']); ?></td><td><?php echo e($detalle['entidad']); ?><?php echo e($detalle['entidad_id'] ? ': #'.$detalle['entidad_id'] : ''); ?></td><td><span class="tc-audit__status tc-audit__status--<?php echo e(in_array(mb_strtolower((string) $detalle['resultado']), ['denegado', 'fallo', 'fallido'], true) ? 'danger' : (in_array(mb_strtolower((string) $detalle['resultado']), ['advertencia', 'revertido'], true) ? 'warning' : 'success')); ?>"><?php echo e($detalle['resultado']); ?></span></td><td><button type="button" class="tc-audit__detail-button" data-audit-detail="<?php echo e($detalle['id']); ?>"><i class="bi bi-eye"></i> Ver detalle</button></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="7" class="tc-aa__empty">No hay eventos para los filtros aplicados.</td></tr><?php endif; ?></tbody></table></div><?php if($pagina['paginacion']->hasPages()): ?><footer class="tc-audit__pagination"><span>Página <?php echo e($pagina['paginacion']->currentPage()); ?> de <?php echo e($pagina['paginacion']->lastPage()); ?></span><nav class="tc-audit__pagination-nav" aria-label="Paginación de auditoría"><?php if($pagina['paginacion']->onFirstPage()): ?><span class="tc-audit__pagination-control is-disabled" aria-hidden="true"><i class="bi bi-chevron-left"></i></span><?php else: ?><a class="tc-audit__pagination-control" href="<?php echo e($pagina['paginacion']->previousPageUrl()); ?>" rel="prev" aria-label="Página anterior"><i class="bi bi-chevron-left"></i></a><?php endif; ?> <?php for($page = 1; $page <= $pagina['paginacion']->lastPage(); $page++): ?><a class="tc-audit__pagination-page<?php echo e($page === $pagina['paginacion']->currentPage() ? ' is-active' : ''); ?>" href="<?php echo e($pagina['paginacion']->url($page)); ?>" <?php if($page === $pagina['paginacion']->currentPage()): ?> aria-current="page" <?php endif; ?>><?php echo e($page); ?></a><?php endfor; ?> <?php if($pagina['paginacion']->hasMorePages()): ?><a class="tc-audit__pagination-control" href="<?php echo e($pagina['paginacion']->nextPageUrl()); ?>" rel="next" aria-label="Página siguiente"><i class="bi bi-chevron-right"></i></a><?php else: ?><span class="tc-audit__pagination-control is-disabled" aria-hidden="true"><i class="bi bi-chevron-right"></i></span><?php endif; ?></nav></footer><?php endif; ?></section>

